// Parse Slack slash command
const event = $input.item.json.event || $input.item.json || {};
const text = event.text || $input.item.json.text || '';
const userId = event.user || $input.item.json.user || '';
const channelId = event.channel || $input.item.json.channel || '';

// Parse command: /pkg-check <package> or /pkg-update <package>
const commandMatch = text.match(/\/(pkg-check|pkg-update)\s+(\S+)/);

if (!commandMatch) {
  return { json: { error: 'Invalid command format. Use: /pkg-check <package> or /pkg-update <package>', skip: true } };
}

const command = commandMatch[1]; // 'pkg-check' or 'pkg-update'
const packageName = commandMatch[2];

return {
  json: {
    command: command,
    packageName: packageName,
    userId: userId,
    channelId: channelId,
    action: command === 'pkg-update' ? 'update' : 'check'
  }
};

// Parse Factory version from OBS
const response = $input.item.json.body || {};
const packageName = $input.item.json.packageName;

let factoryVersion = 'unknown';

if (response.project && response.project.repository) {
  const repos = response.project.repository;
  for (const repo of repos) {
    if (repo.path && repo.path.length > 0) {
      const path = repo.path.find(p => p.name === 'x86_64');
      if (path && path.version) {
        factoryVersion = path.version;
        break;
      }
    }
  }
}

return {
  json: {
    ...$input.item.json,
    factoryVersion: factoryVersion
  }
};

// Compare versions and determine if update needed
const upstreamData = $input.item.json.body || {};
const factoryVersion = $input.item.json.factoryVersion;
const packageName = $input.item.json.packageName;

let upstreamVersion = 'unknown';
let updateNeeded = false;

if (upstreamData.projects && upstreamData.projects.length > 0) {
  upstreamVersion = upstreamData.projects[0].latest_version || 'unknown';
}

// Simple version comparison
if (factoryVersion !== 'unknown' && upstreamVersion !== 'unknown') {
  updateNeeded = upstreamVersion !== factoryVersion;
}

return {
  json: {
    ...$input.item.json,
    upstreamVersion: upstreamVersion,
    updateNeeded: updateNeeded
  }
};

