// Parse AI response and extract structured data
const aiOutput = $input.item.json.output || $input.item.json.text || '';
const packageName = $input.item.json.packageName || 'unknown';

// Extract changelog if present
let aiChangelog = '';
const changelogMatch = aiOutput.match(/changelog[\s\S]*?([*]\s+[^\n]+[\s\S]*?)(?=\n\n|$)/i);
if (changelogMatch) {
  aiChangelog = changelogMatch[1].trim();
} else {
  // Generate default changelog
  aiChangelog = `* ${new Date().toLocaleDateString('en-US', {weekday: 'short', year: 'numeric', month: 'short', day: 'numeric'})} Maintainer <maintainer@example.com> - ${$input.item.json.upstreamVersion}\n- Update to version ${$input.item.json.upstreamVersion}`;
}

// Extract recommendations
let aiRecommendation = 'proceed';
if (aiOutput.toLowerCase().includes('caution') || aiOutput.toLowerCase().includes('manual')) {
  aiRecommendation = 'caution';
} else if (aiOutput.toLowerCase().includes('proceed') || aiOutput.toLowerCase().includes('safe')) {
  aiRecommendation = 'proceed';
}

// Extract risk assessment
let aiRiskLevel = 'low';
if (aiOutput.toLowerCase().includes('high risk') || aiOutput.toLowerCase().includes('breaking')) {
  aiRiskLevel = 'high';
} else if (aiOutput.toLowerCase().includes('medium risk') || aiOutput.toLowerCase().includes('compatibility')) {
  aiRiskLevel = 'medium';
}

return {
  json: {
    ...$input.item.json,
    aiAnalysis: aiOutput,
    aiChangelog: aiChangelog,
    aiRecommendation: aiRecommendation,
    aiRiskLevel: aiRiskLevel,
    aiConsiderations: aiOutput.split('\n').filter(line => line.includes('consider') || line.includes('risk') || line.includes('impact')).join('\n')
  }
};

// Build Kubernetes Job manifest
const packageName = $input.item.json.packageName;
const factoryVersion = $input.item.json.factoryVersion;
const upstreamVersion = $input.item.json.upstreamVersion;
const timestamp = Date.now();
const aiChangelog = $input.item.json.aiChangelog || "";
const aiRiskLevel = $input.item.json.aiRiskLevel || "low";

// Sanitize job name for Kubernetes (lowercase, alphanumeric and hyphens only, max 63 chars)
let sanitizedName = `obs-package-update-${packageName}-${timestamp}`.toLowerCase()
  .replace(/[^a-z0-9-]/g, '-')
  .replace(/^-+|-+$/g, '')
  .substring(0, 63);
if (sanitizedName.endsWith('-')) {
  sanitizedName = sanitizedName.slice(0, -1);
}
if (sanitizedName.startsWith('-')) {
  sanitizedName = sanitizedName.substring(1);
}
if (!sanitizedName) {
  sanitizedName = 'n8n-job-' + Date.now();
}

const jobManifest = {
  apiVersion: 'batch/v1',
  kind: 'Job',
  metadata: {
    name: sanitizedName,
    namespace: 'n8n',
    annotations: {
      'ai.changelog': aiChangelog,
      'ai.risk-level': aiRiskLevel
    }
  },
  spec: {
    ttlSecondsAfterFinished: 3600,
    backoffLimit: 1,
    template: {
      spec: {
        restartPolicy: 'Never',
        containers: [{
          name: 'automation-worker',
          image: 'registry.opensuse.org/opensuse/tumbleweed:latest',
          command: ['/bin/sh', '-c', `echo 'Package: ${packageName}, Factory: ${factoryVersion}, Upstream: ${upstreamVersion}'; sleep 30`]
        }]
      }
    }
  }
};

return {
  json: {
    ...$input.item.json,
    jobManifest: jobManifest
  }
};

